import{z as A,x as d,o as t,c as p,q as n,j as o,D as e,d as E,s as r,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"VLM 幻觉与 POPE","description":"","frontmatter":{"title":"VLM 幻觉与 POPE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vlm-hallucination.md","filePath":"llm/vlm-hallucination.md","lastUpdated":1791413859000}'),B={name:"llm/vlm-hallucination.md"};function P(m,a,u,h,c,f){const i=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="vlm-幻觉与-pope" tabindex="-1">VLM 幻觉与 POPE <a class="header-anchor" href="#vlm-幻觉与-pope" aria-label="Permalink to &quot;VLM 幻觉与 POPE&quot;">​</a></h1><div class="epigraph"><p>语言模型擅长把「像有」说圆。视觉前缀若只提供主题级证据，物体名词会从语言先验里补出来。</p><footer>—— Li 等 Evaluating Object Hallucination in Large Vision-Language Models（POPE）</footer></div><p><a href="/llm/visual-instruction-data">上一课</a>让模型敢谈图。主干<a href="/llm/hallucination-taxonomy">幻觉分类</a>写的是文本侧假话类型。本课缺口是视觉特有的物体幻觉：图中没有的东西被说成有。后课定位默认：只靠「是/否有某物」不够，还要把名词钉到格子上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">语言先验补名词，像填字游戏猜词：句子写「厨房里有____」，就算图里根本没有，语言模型也会顺着搭配填「冰箱」。视觉证据越弱，先验的笔迹越重——幻觉不是「看错了」，而是「没看也敢写」。</span></p><p>开放描述的奖励是流畅与覆盖。指令数据里常见「图中有……」句式，语言模型会把共现物体写进回答——厕所场景就「有洗手台」，即使 <a href="/llm/vit-as-encoder">ViT</a> 的 patch 没提供该证据。这与 CLIP 全局向量对不上细物体是同一病：对比空间与标题先验都偏名词，不偏「不存在」。</p><p>自由描述难以自动判假。POPE（Polling-based Object Probing Evaluation）改成探测：对图问「图中有 {object} 吗？」正例来自真实标注物体，负例来自随机、流行或对抗共现。准确率、精确率、召回、Yes 比率分开报——Yes 偏高就是乱认。<span class="marginnote">「对抗负例」专挑最常与场景共现的物体提问（厕所问洗手台）——专戳语言先验最容易带走答案的软肋，是三类负例里最难的一项；模型在它上面翻车，说明先验压过了视觉证据。</span></p><p><span class="marginnote">POPE 测的是物体有无，不是属性、计数、关系。描述里编造颜色或「三只」仍可在 POPE 上及格。不要用它替代 OCR 与指代评测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练侧：在指令里加入否定与拒答、降低无根据列举、用存在性问答做辅助损失。解码侧：降低鼓励覆盖的采样，或对物体名词做与视觉一致的约束（后课 grounding 更硬）。评测必须含 POPE 三类负例，且与自由描述的人评分列。不要用 <a href="/llm/clip">CLIP</a> 余弦当「没幻觉」的证明。</p>',10)),(t(),o(s,null,{default:e(()=>[r(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DESC%5B%22%E5%BC%80%E6%94%BE%E6%8F%8F%E8%BF%B0%22%5D%20--%3E%20PRIOR%5B%22%E8%AF%AD%E8%A8%80%E7%89%A9%E4%BD%93%E5%85%88%E9%AA%8C%22%5D%0A%20%20PRIOR%20--%3E%20HALL%5B%22%E7%BC%96%E9%80%A0%E7%89%A9%E4%BD%93%22%5D%0A%20%20PROBE%5B%22POPE%20%E6%98%AF%E5%90%A6%E9%A2%98%22%5D%20--%3E%20YN%5B%22%E6%9C%89%E6%97%A0%E5%88%A4%E5%86%B3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[E("因果 LLM 在视觉前缀之后继续写，每一步仍是词表 softmax。若视觉键值对「有没有猫」区分弱，而「室内、沙发」强烈激活猫的语言共现，Yes 与名词就会被先验带走。"),l("a",{href:"/llm/llava-projector"},"LLaVA 投影器"),E(" 越浅、ViT 越冻，这个通道越依赖 CLIP 已经提取的概念，未提取的细物更容易被语言补全。")],-1)),a[5]||(a[5]=l("p",null,"POPE 一轮探测具体怎么跑、指标从哪来：",-1)),(t(),o(s,null,{default:e(()=>[r(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20GT%5B%22%E7%9C%9F%E5%AE%9E%E6%A0%87%E6%B3%A8%E7%89%A9%E4%BD%93%22%5D%20--%3E%20PQ%5B%22%E6%AD%A3%E4%BE%8B%E9%97%AE%E9%A2%98%20%E5%9B%BE%E4%B8%AD%E6%9C%89%E7%8C%AB%E5%90%97%22%5D%0A%20%20NEG%5B%22%E8%B4%9F%E4%BE%8B%E9%87%87%E6%A0%B7%20%E9%9A%8F%E6%9C%BA%2F%E6%B5%81%E8%A1%8C%2F%E5%AF%B9%E6%8A%97%22%5D%20--%3E%20NQ%5B%22%E8%B4%9F%E4%BE%8B%E9%97%AE%E9%A2%98%20%E5%9B%BE%E4%B8%AD%E6%9C%89%E6%B4%97%E6%89%8B%E5%8F%B0%E5%90%97%22%5D%0A%20%20PQ%20--%3E%20M%5B%22VLM%20%E7%AD%94%20yes%20%E6%88%96%20no%22%5D%0A%20%20NQ%20--%3E%20M%0A%20%20M%20--%3E%20MET%5B%22%E5%87%86%E7%A1%AE%E7%8E%87%20%E7%B2%BE%E7%A1%AE%E7%8E%87%20%E5%8F%AC%E5%9B%9E%20Yes%20%E6%AF%94%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：若模型对任何物体都答 yes，召回是 100%，但精确率跌到约等于正例占比（POPE 通常设 50%），Yes 比率飙到 100%。三个数一起看，才能拆出「全答有」这种满分召回的作弊解——这正是只看单一指标会漏掉的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>压幻觉会伤召回：模型改口说「看不清」。下一课把问题改成指代与框，让「说有」必须对应空间证据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物体幻觉是语言先验在弱视觉证据上补名词。</li><li>POPE 用是否探测把描述不可判变成可自动评。</li><li>Yes 比率与精确率要一起看。</li><li>出处：Li 等 POPE；指令来源见 LLaVA。</li></ul>',5))])}const C=A(B,[["render",P]]);export{D as __pageData,C as default};
